<template>
  <div v-if="project" class="case-shell">
    <section class="case-hero">
      <div class="case-image">
        <img class="case-image-backdrop" :src="project.image" alt="" aria-hidden="true">
        <img class="case-image-main" :src="project.image" :alt="project.title">
        <div v-if="project.isConfidential" class="nda-overlay" aria-label="NDA protected project">
          <span class="lock-icon" aria-hidden="true"></span>
          <strong>NDA</strong>
          <small>Unannounced multiplayer IP</small>
        </div>
        <p v-if="project.imageCaption" class="image-caption">{{ project.imageCaption }}</p>
      </div>
      <div class="case-intro">
        <router-link class="back-link" to="/projects">Back to projects</router-link>
        <p class="mono-label">{{ project.role }}</p>
        <h1>{{ project.title }}</h1>
        <p class="case-summary" v-html="project.summaryHtml || project.summary"></p>
        <div class="tag-row">
          <span v-for="tag in project.tags" :key="tag">{{ tag }}</span>
        </div>
        <div class="actions">
          <a
            v-for="link in project.links"
            :key="link.url"
            :href="link.url"
            target="_blank"
            rel="noopener"
          >
            {{ link.label }}
          </a>
        </div>
      </div>
    </section>

    <section class="case-grid">
      <article>
        <p class="mono-label">Why it matters</p>
        <h2>Problem and value</h2>
        <p v-html="project.relevanceHtml || project.relevance"></p>
      </article>
    </section>

    <section v-if="project.article" class="article-shell">
      <article class="article-intro">
        <p class="mono-label">Project article</p>
        <h2>What the work achieved</h2>
        <div class="article-copy" v-html="project.article.positioningHtml"></div>
      </article>

      <div class="article-sections">
        <article
          v-for="section in project.article.sections"
          :key="section.title"
          class="article-block"
        >
          <h3>{{ section.title }}</h3>
          <div class="article-copy" v-html="section.bodyHtml"></div>
        </article>
      </div>

      <div class="signal-grid">
        <article class="signal-card">
          <p class="mono-label">User value</p>
          <h3>{{ project.article.userValueTitle || 'Who the work helped' }}</h3>
          <ul>
            <li v-for="item in project.article.userValue" :key="item">{{ item }}</li>
          </ul>
        </article>

        <article class="signal-card">
          <p class="mono-label">Project value</p>
          <h3>{{ project.article.projectValueTitle || 'What became easier' }}</h3>
          <ul>
            <li v-for="item in project.article.projectValue" :key="item">{{ item }}</li>
          </ul>
        </article>
      </div>

      <section v-if="project.article.architecture" class="architecture-section">
        <div class="section-heading">
          <p class="mono-label">Architecture</p>
          <h2>{{ project.article.architecture.title }}</h2>
          <p v-if="project.article.architecture.summary">{{ project.article.architecture.summary }}</p>
        </div>

        <div class="architecture-graph" :style="architectureGridStyle">
          <article
            v-for="module in project.article.architecture.modules"
            :key="module.name"
            class="architecture-module"
          >
            <p class="mono-label">{{ module.type }}</p>
            <h3>{{ module.name }}</h3>
            <div class="architecture-nodes">
              <span v-for="node in module.nodes" :key="node">{{ node }}</span>
            </div>
          </article>
        </div>
      </section>

      <section
        v-if="visibleEvidence.length || trackFitItems.length"
        class="support-section"
        :class="{
          'support-section-compact': visibleEvidence.length <= 1,
          'support-section-fit-only': !visibleEvidence.length,
          'support-section-has-code': hasCodeEvidence
        }"
      >
        <div v-if="visibleEvidence.length" class="support-column resource-column">
          <div class="section-heading">
            <p class="mono-label">Resources</p>
            <h2>Additional Resources</h2>
          </div>

          <div class="evidence-grid">
            <article
              v-for="item in visibleEvidence"
              :key="item.title"
              class="evidence-card"
              :class="[`evidence-${item.type}`, { 'evidence-confidential': project.isConfidential && item.type === 'image' }]"
            >
              <p class="mono-label">{{ evidenceLabel(item.type) }}</p>
              <h3>{{ item.title }}</h3>
              <p>{{ item.description }}</p>
              <video
                v-if="item.type === 'video' && item.src"
                class="evidence-video-media"
                :src="item.src"
                autoplay
                loop
                muted
                playsinline
                preload="metadata"
              ></video>
              <img
                v-if="item.type === 'image' && item.src"
                class="evidence-image-media"
                :src="item.src"
                :alt="item.title"
              >
              <div v-if="project.isConfidential && item.type === 'image'" class="nda-card-overlay" aria-label="NDA protected project">
                <span class="lock-icon" aria-hidden="true"></span>
                <strong>NDA</strong>
              </div>
              <p v-if="project.imageCaption && item.type === 'image'" class="image-caption evidence-caption">
                {{ project.imageCaption }}
              </p>
              <div v-if="item.type === 'code' && item.content" class="code-frame">
                <div class="code-toolbar">
                  <span>{{ codeLanguage(item) }}</span>
                  <span>excerpt</span>
                </div>
                <pre><code v-html="highlightCode(item.content)"></code></pre>
              </div>
              <a
                v-if="item.url"
                :href="item.url"
                target="_blank"
                rel="noopener"
              >
                Open resource
              </a>
            </article>
          </div>
        </div>

        <div v-if="trackFitItems.length" class="support-column">
          <div class="section-heading">
            <p class="mono-label">Project fit</p>
            <h2>Where this work connects.</h2>
          </div>
          <div class="track-fit-grid">
            <article v-for="item in trackFitItems" :key="item.label">
              <p class="mono-label">{{ item.label }}</p>
              <p>{{ item.copy }}</p>
            </article>
          </div>
        </div>
      </section>
    </section>
  </div>
  <div v-else class="case-shell missing">
    <h1>Project not found</h1>
    <router-link class="back-link" to="/projects">Back to projects</router-link>
  </div>
</template>

<script>
import portfolio from '@/services/portfolio'

export default {
  computed: {
    project() {
      return portfolio.getProject(this.$route.params.id)
    },
    visibleEvidence() {
      const evidence = this.project?.article?.evidence || []
      return evidence.filter(item => {
        if (!item || item.type === 'placeholder') {
          return false
        }
        return Boolean(item.url || item.content || item.src)
      })
    },
    trackFitItems() {
      const trackFit = this.project?.article?.trackFit || {}
      return [
        { label: 'Engineering', copy: trackFit.engineering },
        { label: 'Games', copy: trackFit.games }
      ].filter(item => item.copy)
    },
    hasCodeEvidence() {
      return this.visibleEvidence.some(item => item.type === 'code')
    },
    architectureGridStyle() {
      const modules = this.project?.article?.architecture?.modules || []
      return {
        '--architecture-module-count': Math.max(1, modules.length)
      }
    }
  },
  methods: {
    evidenceLabel(type) {
      const labels = {
        code: 'Code',
        image: 'Image',
        video: 'Video',
        diagram: 'Diagram',
        repo: 'Repository',
        document: 'Document'
      }
      return labels[type] || 'Resource'
    },
    codeLanguage(item) {
      return item.language || 'C++ / Unreal'
    },
    escapeHtml(value) {
      return String(value || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#039;')
    },
    highlightCppLine(line) {
      if (line.trim().startsWith('#')) {
        return `<span class="code-preprocessor">${this.escapeHtml(line)}</span>`
      }

      const commentIndex = line.indexOf('//')
      const codePart = commentIndex >= 0 ? line.slice(0, commentIndex) : line
      const commentPart = commentIndex >= 0 ? line.slice(commentIndex) : ''
      const placeholders = []

      let html = this.escapeHtml(codePart)
      html = html.replace(/(&quot;.*?&quot;)/g, match => {
        const token = `@@ASHEN_STRING_${placeholders.length}@@`
        placeholders.push(`<span class="code-string">${match}</span>`)
        return token
      })

      html = html
        .replace(/\b(bool|const|float|double|int|int32|uint8|void|return|if|else|for|while|static|class|struct|public|private|protected|virtual|override|nullptr|true|false|auto)\b/g, '<span class="code-keyword">$1</span>')
        .replace(/\b(F[A-Z]\w*|U[A-Z]\w*|A[A-Z]\w*|E[A-Z]\w*|T[A-Z]\w*)\b/g, '<span class="code-type">$1</span>')
        .replace(/\b([A-Za-z_]\w*)(?=\()/g, '<span class="code-function">$1</span>')

      placeholders.forEach((value, index) => {
        html = html.replace(`@@ASHEN_STRING_${index}@@`, value)
      })

      if (!commentPart) {
        return html
      }

      return `${html}<span class="code-comment">${this.escapeHtml(commentPart)}</span>`
    },
    highlightCode(value) {
      return String(value || '')
        .split('\n')
        .map(line => this.highlightCppLine(line))
        .join('\n')
    }
  }
}
</script>

